begin;
set search_path=extensions,public;
grant usage on schema extensions to hsr_worker,authenticated;
select plan(22);
select has_function('hsr','read_scan_job_permission',array['uuid','uuid','uuid','bigint'],'PermissionSnapshotFunctionExists');
select ok(not has_function_privilege('anon','hsr.read_scan_job_permission(uuid,uuid,uuid,bigint)','EXECUTE'),'PermissionSnapshotDeniesAnonymousExecute');
select ok(not has_function_privilege('hsr_worker','hsr.read_scan_job_permission(uuid,uuid,uuid,bigint)','EXECUTE'),'PermissionSnapshotDoesNotExpandWorkerRole');
select ok(has_function_privilege('authenticated','hsr.read_scan_job_permission(uuid,uuid,uuid,bigint)','EXECUTE'),'PermissionSnapshotAllowsAuthenticatedScopedRead');
insert into auth.users(id) values ('79000000-0000-0000-0000-000000000001'),('79000000-0000-0000-0000-000000000002');
insert into hsr.organizations(id,name) values ('79000000-0000-0000-0000-000000000003','Permission original workspace'),('79000000-0000-0000-0000-000000000004','Permission foreign workspace');
insert into hsr.memberships values ('79000000-0000-0000-0000-000000000003','79000000-0000-0000-0000-000000000001'),('79000000-0000-0000-0000-000000000004','79000000-0000-0000-0000-000000000002');
select set_config('request.jwt.claim.sub','79000000-0000-0000-0000-000000000001',true);
set local role authenticated;
create temporary table recorded as select * from hsr.create_recorded_traversal('79000000-0000-0000-0000-000000000003','79000000-0000-0000-0000-000000000005',1);
reset role;
set local role hsr_worker;
create temporary table claimed as select * from hsr.claim_scan_job_with_traversal('79000000-0000-0000-0000-000000000006',60);
reset role;
create temporary table lease_before as select expires_at,clock_timestamp() as read_started from hsr.job_leases where job_id=(select job_id from recorded);
set local role authenticated;
create temporary table permission as select * from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000003',(select scan_id from recorded),(select job_id from recorded),1);
reset role;
select results_eq($$select organization_id,scan_id,job_id,generation from permission$$,$$select '79000000-0000-0000-0000-000000000003'::uuid,scan_id,job_id,1::bigint from recorded$$,'PermissionSnapshotPinsExactCurrentJobAndGeneration');
select is((select status from permission),'Active','PermissionSnapshotReportsActualActiveLease');
select ok((select checked_at>=read_started and checked_at<=clock_timestamp() from permission cross join lease_before),'PermissionSnapshotUsesDatabaseClock');
select is((select expires_at from permission),(select expires_at from lease_before),'PermissionSnapshotRetainsActualExpiry');
select is((select array_agg(k order by k) from permission p,jsonb_object_keys(to_jsonb(p)) k),array['checked_at','expires_at','generation','job_id','organization_id','scan_id','status']::text[],'PermissionSnapshotContainsNoTokenHashOrWorkerCredential');
select is((select expires_at from hsr.job_leases where job_id=(select job_id from recorded)),(select expires_at from lease_before),'PermissionSnapshotDoesNotRenewOrChangeLease');
set local role authenticated;
select is((select count(*) from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000003',(select scan_id from recorded),(select job_id from recorded),2)),0::bigint,'PermissionSnapshotCannotReadAnotherGeneration');
select is((select count(*) from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000003',(select scan_id from recorded),'79000000-0000-0000-0000-000000000007',1)),0::bigint,'PermissionSnapshotCannotSubstituteAnotherJob');
select is((select count(*) from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000003','79000000-0000-0000-0000-000000000008',(select job_id from recorded),1)),0::bigint,'PermissionSnapshotCannotSubstituteAnotherScan');
select throws_ok($$select * from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000004','79000000-0000-0000-0000-000000000008','79000000-0000-0000-0000-000000000007',1)$$,'42501','PERMISSION_SNAPSHOT_MEMBERSHIP_REQUIRED','PermissionSnapshotDeniesForeignWorkspace');
reset role;
update hsr.job_leases set expires_at=clock_timestamp()-interval '1 second' where job_id=(select job_id from recorded);
set local role authenticated;
create temporary table expired as select * from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000003',(select scan_id from recorded),(select job_id from recorded),1);
reset role;
select is((select status from expired),'Expired','PermissionSnapshotNamesExpiredAuthorityWithoutChangingExecution');
select ok((select expires_at<=checked_at from expired),'PermissionSnapshotExpiryAgreesWithItsRecordedClock');
delete from hsr.job_leases where job_id=(select job_id from recorded);
set local role authenticated;
create temporary table missing as select * from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000003',(select scan_id from recorded),(select job_id from recorded),1);
reset role;
select is((select status from missing),'Missing','PermissionSnapshotNamesMissingMatchingAuthority');
select ok((select expires_at is null from missing),'PermissionSnapshotDoesNotInventMissingExpiry');
update hsr.scan_jobs set state='blocked' where id=(select job_id from recorded);
set local role authenticated;
select is((select count(*) from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000003',(select scan_id from recorded),(select job_id from recorded),1)),0::bigint,'PermissionSnapshotCannotAttachToTerminalExecution');
reset role;
delete from hsr.memberships where organization_id='79000000-0000-0000-0000-000000000003';
set local role authenticated;
select throws_ok($$select * from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000003','79000000-0000-0000-0000-000000000008','79000000-0000-0000-0000-000000000007',1)$$,'42501','PERMISSION_SNAPSHOT_MEMBERSHIP_REQUIRED','PermissionSnapshotChecksRevocationOnEveryRead');
reset role;
set local role anon;
select throws_ok($$select * from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000003','79000000-0000-0000-0000-000000000008','79000000-0000-0000-0000-000000000007',1)$$,'42501','permission denied for schema hsr','PermissionSnapshotAnonymousCannotReadEvenWithKnownIds');
reset role;
set local role authenticated;
select throws_ok($$select * from hsr.read_scan_job_permission('79000000-0000-0000-0000-000000000003','79000000-0000-0000-0000-000000000008','79000000-0000-0000-0000-000000000007',0)$$,'22023','INVALID_PERMISSION_SNAPSHOT_SCOPE','PermissionSnapshotRejectsInvalidScope');
reset role;
select * from finish();
rollback;
